#!/usr/bin/env node
// scaffold-docker-compose.js — v78 emit project-root docker-compose.yml
// with postgres + backend + frontend services. Reads ports from
// frontend/.env + backend/.env (or sensible defaults).
//
// Idempotent. Marker: '# Generated by scaffold-docker-compose'.
'use strict';

var fs = require('fs');
var path = require('path');

function parseArgs(argv) {
  var out = {};
  for (var i = 2; i < argv.length; i++) {
    var a = argv[i];
    if (a === '--target') out.target = argv[++i];
    else if (a === '--force') out.force = true;
    else if (a === '--dry-run') out.dryRun = true;
    else if (a === '--verbose' || a === '-v') out.verbose = true;
  }
  if (!out.target) { console.error('Usage: scaffold-docker-compose --target PROJECT_ROOT'); process.exit(1); }
  return out;
}

function marker() { return '# Generated by scaffold-docker-compose — DO NOT EDIT BY HAND. Re-run to refresh.'; }

function envValue(envPath, key, fallback) {
  if (!fs.existsSync(envPath)) return fallback;
  var content = fs.readFileSync(envPath, 'utf-8');
  var re = new RegExp('^' + key + '=([^\n#]+)', 'm');
  var m = re.exec(content);
  return m ? m[1].trim().replace(/^["']|["']$/g, '') : fallback;
}

function writeIfManaged(file, content, force, dryRun) {
  if (fs.existsSync(file)) {
    var existing = fs.readFileSync(file, 'utf-8');
    if (!/Generated by scaffold-docker-compose/.test(existing) && !force) {
      return { written: false, reason: 'exists-handauthored' };
    }
    if (existing === content) return { written: false, reason: 'unchanged' };
  }
  if (dryRun) return { written: false, reason: 'dry-run' };
  fs.mkdirSync(path.dirname(file), { recursive: true });
  fs.writeFileSync(file, content);
  return { written: true };
}

function main() {
  var args = parseArgs(process.argv);
  var bePort = envValue(path.join(args.target, 'backend/.env'), 'PORT', '3000');
  var fePort = envValue(path.join(args.target, 'frontend/.env'), 'PORT', '5173');
  var pgDb = envValue(path.join(args.target, 'backend/.env'), 'POSTGRES_DB', 'app');
  var pgUser = envValue(path.join(args.target, 'backend/.env'), 'POSTGRES_USER', 'postgres');
  var pgPass = envValue(path.join(args.target, 'backend/.env'), 'POSTGRES_PASSWORD', 'postgres');

  var compose = [
    marker(),
    "services:",
    "  postgres:",
    "    image: postgres:16-alpine",
    "    restart: unless-stopped",
    "    environment:",
    "      POSTGRES_DB: " + pgDb,
    "      POSTGRES_USER: " + pgUser,
    "      POSTGRES_PASSWORD: " + pgPass,
    "    ports:",
    '      - "5432:5432"',
    "    volumes:",
    "      - pg_data:/var/lib/postgresql/data",
    "    healthcheck:",
    '      test: ["CMD-SHELL", "pg_isready -U ' + pgUser + ' -d ' + pgDb + '"]',
    "      interval: 5s",
    "      timeout: 5s",
    "      retries: 5",
    "",
    "  backend:",
    "    build:",
    "      context: ./backend",
    "      dockerfile: Dockerfile",
    "    restart: unless-stopped",
    "    depends_on:",
    "      postgres:",
    "        condition: service_healthy",
    "    env_file:",
    "      - ./backend/.env",
    "    ports:",
    '      - "' + bePort + ':' + bePort + '"',
    "",
    "  frontend:",
    "    build:",
    "      context: ./frontend",
    "      dockerfile: Dockerfile",
    "    restart: unless-stopped",
    "    depends_on:",
    "      - backend",
    "    env_file:",
    "      - ./frontend/.env",
    "    ports:",
    '      - "' + fePort + ':' + fePort + '"',
    "",
    "volumes:",
    "  pg_data:",
    "",
  ].join('\n');

  var r = writeIfManaged(path.join(args.target, 'docker-compose.yml'), compose, args.force, args.dryRun);
  console.log('scaffold-docker-compose: docker-compose.yml=' + (r.written ? 'wrote' : r.reason) + ' (be:' + bePort + ' fe:' + fePort + ' pg:' + pgDb + ')');
}

main();
